import { buildNonceAttribute } from "./html-escape.js";
import { PROJECT_STYLESHEET_ID } from "./project-stylesheet-ids.js";
export function getPreviewStylesheetLink() {
    // Deliberately a stable URL. The route serves this stylesheet with
    // `Cache-Control: no-cache` plus an ETag, so the browser already revalidates
    // before every use and gets a 304 when nothing changed. A per-render
    // cache-busting query defeats that: each render asks for a URL the cache has
    // never seen, forcing a full download of a blocking stylesheet on every page
    // view. Dev reloads stay fresh through the same revalidation, and the HMR
    // client re-points this link explicitly when styles change.
    return `<link id="${PROJECT_STYLESHEET_ID}" rel="stylesheet" href="/_vf_styles/styles.css">`;
}
export function getDevStyles(nonce) {
    const nonceAttr = buildNonceAttribute(nonce);
    return `
  <style${nonceAttr}>
    .dev-indicator {
      position: fixed;
      bottom: 1rem;
      right: 1rem;
      background: #3b82f6;
      color: white;
      padding: 0.5rem 1rem;
      border-radius: 0.5rem;
      font-size: 0.875rem;
      z-index: 9999;
    }

    #veryfront-error-overlay {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      z-index: 999999;
      background: rgba(0,0,0,0.85);
      color: white;
      font-family: monospace;
      overflow: auto;
      padding: 2rem;
    }
  </style>`;
}
export function getDevScripts(_hmrPort, nonce) {
    const nonceAttr = buildNonceAttribute(nonce);
    return `
  <script type="module" src="/_veryfront/rsc/client.js"${nonceAttr}></script>
  <script type="module" src="/_veryfront/hmr.js"${nonceAttr}></script>`;
}
export function getProdScripts(_slug, nonce) {
    const nonceAttr = buildNonceAttribute(nonce);
    return `
  <script type="module" src="/_veryfront/rsc/client.js"${nonceAttr}></script>`;
}
export function getStudioScripts(options) {
    const nonceAttr = buildNonceAttribute(options.nonce);
    const bridgeConfig = {
        projectId: options.projectId,
        pageId: options.pageId,
        pagePath: options.pagePath ?? options.pageId,
    };
    if (options.wsUrl)
        bridgeConfig.wsUrl = options.wsUrl;
    if (options.yjsGuid)
        bridgeConfig.yjsGuid = options.yjsGuid;
    const sourceHashScript = options.sourceHash
        ? `<script${nonceAttr}>window.__VERYFRONT_SOURCE_HASH__=${JSON.stringify(options.sourceHash).replace(/</g, "\\u003c")};</script>\n  `
        : "";
    // Escape </script> sequences to prevent XSS breakout from inline JSON
    const safeJson = JSON.stringify(bridgeConfig).replace(/</g, "\\u003c");
    const configScript = `<script${nonceAttr}>window.__VF_BRIDGE_CONFIG__=${safeJson};</script>`;
    return `
  ${sourceHashScript}${configScript}
  <script type="module" src="/_veryfront/studio-bridge.js"${nonceAttr}></script>`;
}
